#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "../include/beamer_generator.h"

/*
 * Statistics used by the presentation.
 *
 * These values are calculated directly from the token array
 * produced by the scanner.
 */
typedef struct {
    size_t keyword_count;
    size_t identifier_count;
    size_t constant_count;
    size_t string_literal_count;
    size_t operator_count;
    size_t punctuator_count;
    size_t error_count;
    size_t total_tokens;
} BeamerStats;


/*
 * Calculates lexical-category statistics from the tokens
 * generated by the scanner.
 */
static void calculate_stats(
    const Token *tokens,
    size_t token_count,
    BeamerStats *stats
) {
    memset(stats, 0, sizeof(BeamerStats));

    for (size_t i = 0; i < token_count; i++) {

        switch (tokens[i].category) {

            case CAT_KEYWORD:
                stats->keyword_count++;
                break;

            case CAT_IDENTIFIER:
                stats->identifier_count++;
                break;

            case CAT_CONSTANT:
                stats->constant_count++;
                break;

            case CAT_STRING_LITERAL:
                stats->string_literal_count++;
                break;

            case CAT_OPERATOR:
                stats->operator_count++;
                break;

            case CAT_PUNCTUATOR:
                stats->punctuator_count++;
                break;

            case CAT_ERROR:
                stats->error_count++;
                break;

            case CAT_EOF:
                continue;
        }

        stats->total_tokens++;
    }
}


/*
 * Prints text safely inside LaTeX.
 *
 * Some characters have a special meaning in LaTeX and must
 * therefore be escaped before being written to the .tex file.
 */
static void write_latex_escaped(
    FILE *file,
    const char *text
) {
    if (text == NULL) {
        return;
    }

    while (*text != '\0') {

        switch (*text) {

            case '\\':
                fprintf(file, "\\textbackslash{}");
                break;

            case '{':
                fprintf(file, "\\{");
                break;

            case '}':
                fprintf(file, "\\}");
                break;

            case '$':
                fprintf(file, "\\$");
                break;

            case '&':
                fprintf(file, "\\&");
                break;

            case '#':
                fprintf(file, "\\#");
                break;

            case '_':
                fprintf(file, "\\_");
                break;

            case '%':
                fprintf(file, "\\%%");
                break;

            case '^':
                fprintf(file, "\\textasciicircum{}");
                break;

            case '~':
                fprintf(file, "\\textasciitilde{}");
                break;

            default:
                fputc(*text, file);
                break;
        }

        text++;
    }
}


/*
 * Writes the LaTeX preamble.
 *
 * This part is static and is included in every presentation.
 */
static void write_preamble(FILE *file) {

    fprintf(file,
        "\\documentclass[aspectratio=169]{beamer}\n"
        "\n"
        "\\usetheme{Madrid}\n"
        "\\usecolortheme{default}\n"
        "\n"
        "\\usepackage[utf8]{inputenc}\n"
        "\\usepackage[T1]{fontenc}\n"
        "\\usepackage[spanish]{babel}\n"
        "\\usepackage{listings}\n"
        "\\usepackage{xcolor}\n"
        "\\usepackage{tikz}\n"
        "\\usepackage{pgfplots}\n"
        "\n"
        "\\pgfplotsset{compat=1.18}\n"
        "\\usepgfplotslibrary{polar}\n"
        "\n"
        "\\definecolor{keywordcolor}{RGB}{30,90,180}\n"
        "\\definecolor{identifiercolor}{RGB}{30,30,30}\n"
        "\\definecolor{constantcolor}{RGB}{150,40,150}\n"
        "\\definecolor{stringcolor}{RGB}{20,130,70}\n"
        "\\definecolor{operatorcolor}{RGB}{210,100,20}\n"
        "\\definecolor{punctuatorcolor}{RGB}{90,90,90}\n"
        "\\definecolor{errorcolor}{RGB}{190,30,30}\n"
        "\n"
        "\\lstdefinestyle{cstyle}{\n"
        "    language=C,\n"
        "    basicstyle=\\ttfamily\\small,\n"
        "    keywordstyle=\\color{keywordcolor}\\bfseries,\n"
        "    stringstyle=\\color{stringcolor},\n"
        "    commentstyle=\\color{gray}\\itshape,\n"
        "    numbers=left,\n"
        "    numberstyle=\\tiny\\color{gray},\n"
        "    numbersep=8pt,\n"
        "    frame=single,\n"
        "    breaklines=true,\n"
        "    showstringspaces=false,\n"
        "    tabsize=4\n"
        "}\n"
        "\n"
        "\\title{Proyecto 1: Analizador Léxico}\n"
        "\\subtitle{Scanner para el lenguaje C}\n"
        "\\author{Integrante 1 \\\\ Integrante 2}\n"
        "\\institute{Escuela de Ciencias de la Computación e Informática}\n"
        "\\date{II Semestre 2026}\n"
        "\n"
    );
}


