/*
 * Writes a general explanation of Flex.
 */
static void write_flex_slide(FILE *file) {

    fprintf(file,
        "\\begin{frame}{Uso de Flex}\n"
        "\n"
        "\\begin{itemize}\n"
        "    \\item Flex permite definir patrones mediante "
        "expresiones regulares.\n"
        "\n"
        "    \\item Cada patrón está asociado a una acción "
        "escrita en C.\n"
        "\n"
        "    \\item A partir de un archivo \\texttt{.l}, "
        "Flex genera código fuente en C.\n"
        "\n"
        "    \\item El scanner procesa la entrada y reconoce "
        "los diferentes lexemas.\n"
        "\n"
        "    \\item Cada lexema es clasificado dentro de "
        "una categoría léxica.\n"
        "\\end{itemize}\n"
        "\n"
        "\\vspace{0.4cm}\n"
        "\n"
        "\\begin{block}{Flujo básico}\n"
        "\\texttt{scanner.l}\n"
        "$\\rightarrow$\n"
        "\\texttt{Flex}\n"
        "$\\rightarrow$\n"
        "\\texttt{scanner.yy.c}\n"
        "$\\rightarrow$\n"
        "\\texttt{ejecutable}\n"
        "\\end{block}\n"
        "\n"
        "\\end{frame}\n"
        "\n"
    );
}


/*
 * Writes information about the original source file and the
 * temporary preprocessed file used as input for the scanner.
 */
static void write_input_slide(
    FILE *file,
    const char *source_filename,
    const char *preprocessed_filename
) {

    fprintf(file,
        "\\begin{frame}{Archivos procesados}\n"
        "\n"
        "\\begin{block}{Archivo fuente}\n"
        "\\texttt{"
    );

    write_latex_escaped(file, source_filename);

    fprintf(file,
        "}\n"
        "\\end{block}\n"
        "\n"
        "\\begin{block}{Archivo después del preproceso}\n"
        "\\texttt{"
    );

    write_latex_escaped(file, preprocessed_filename);

    fprintf(file,
        "}\n"
        "\\end{block}\n"
        "\n"
        "El scanner utiliza el archivo temporal generado por "
        "el preprocesador como su entrada real.\n"
        "\n"
        "\\end{frame}\n"
        "\n"
    );
}


/*
 * Writes a summary table containing the lexical categories
 * found by the scanner.
 */
static void write_statistics_slide(
    FILE *file,
    const BeamerStats *stats
) {

    fprintf(file,
        "\\begin{frame}{Resumen del análisis léxico}\n"
        "\n"
        "\\centering\n"
        "\n"
        "\\begin{tabular}{lr}\n"
        "\\textbf{Categoría} & "
        "\\textbf{Cantidad} \\\\ \\hline\n"
        "\n"
        "Palabras reservadas & %zu \\\\\n"
        "Identificadores & %zu \\\\\n"
        "Constantes & %zu \\\\\n"
        "Literales de hilera & %zu \\\\\n"
        "Operadores & %zu \\\\\n"
        "Signos de puntuación & %zu \\\\\n"
        "Errores léxicos & %zu \\\\\n"
        "\\hline\n"
        "\\textbf{Total} & \\textbf{%zu} \\\\\n"
        "\\end{tabular}\n"
        "\n"
        "\\end{frame}\n"
        "\n",

        stats->keyword_count,
        stats->identifier_count,
        stats->constant_count,
        stats->string_literal_count,
        stats->operator_count,
        stats->punctuator_count,
        stats->error_count,
        stats->total_tokens
    );
}


/*
 * Writes a histogram containing the number of tokens
 * in each lexical category.
 */
static void write_histogram(
    FILE *file,
    const BeamerStats *stats
) {

    fprintf(file,
        "\\begin{frame}{Histograma de categorías léxicas}\n"
        "\n"
        "\\centering\n"
        "\n"
        "\\begin{tikzpicture}\n"
        "\n"
        "\\begin{axis}[\n"
        "    ybar,\n"
        "    width=11.5cm,\n"
        "    height=6cm,\n"
        "    ylabel={Cantidad},\n"
        "    symbolic x coords={"
        "Keyword,Identifier,Constant,String,"
        "Operator,Punctuator,Error},\n"
        "    xtick=data,\n"
        "    x tick label style={\n"
        "        rotate=35,\n"
        "        anchor=east,\n"
        "        font=\\scriptsize\n"
        "    },\n"
        "    ymin=0,\n"
        "    nodes near coords,\n"
        "    enlargelimits=0.15\n"
        "]\n"
        "\n"
        "\\addplot coordinates {\n"
        "    (Keyword,%zu)\n"
        "    (Identifier,%zu)\n"
        "    (Constant,%zu)\n"
        "    (String,%zu)\n"
        "    (Operator,%zu)\n"
        "    (Punctuator,%zu)\n"
        "    (Error,%zu)\n"
        "};\n"
        "\n"
        "\\end{axis}\n"
        "\n"
        "\\end{tikzpicture}\n"
        "\n"
        "\\end{frame}\n"
        "\n",

        stats->keyword_count,
        stats->identifier_count,
        stats->constant_count,
        stats->string_literal_count,
        stats->operator_count,
        stats->punctuator_count,
        stats->error_count
    );
}


/*
 * Writes the lexical-error slide.
 */
static void write_error_slide(
    FILE *file,
    const Token *tokens,
    size_t token_count
) {
    size_t error_count = 0;

    for (size_t i = 0; i < token_count; i++) {

        if (tokens[i].category == CAT_ERROR) {
            error_count++;
        }
    }

    fprintf(file,
        "\\begin{frame}{Errores léxicos}\n"
        "\n"
    );

    if (error_count == 0) {

        fprintf(file,
            "\\begin{block}{Resultado}\n"
            "No se encontraron errores léxicos.\n"
            "\\end{block}\n"
        );

    } else {

        fprintf(file,
            "Se encontraron %zu errores léxicos.\n"
            "\n"
            "\\vspace{0.3cm}\n"
            "\n"
            "\\begin{tabular}{lll}\n"
            "\\textbf{Lexema} & "
            "\\textbf{Línea} & "
            "\\textbf{Columna} \\\\ \\hline\n",
            error_count
        );

        for (size_t i = 0; i < token_count; i++) {

            if (tokens[i].category != CAT_ERROR) {
                continue;
            }

            fprintf(file, "\\texttt{");

            write_latex_escaped(
                file,
                tokens[i].lexeme
            );

            fprintf(file,
                "} & %d & %d \\\\\n",
                tokens[i].line,
                tokens[i].column
            );
        }

        fprintf(file,
            "\\end{tabular}\n"
        );
    }

    fprintf(file,
        "\n"
        "\\end{frame}\n"
        "\n"
    );
}


/*
 * Writes one sector of the dynamic pie chart.
 */
static void write_pie_sector(
    FILE *file,
    double start_angle,
    double end_angle,
    const char *color
) {
    if (end_angle <= start_angle) {
        return;
    }

    fprintf(file,
        "\\path[\n"
        "    fill=%s,\n"
        "    draw=white,\n"
        "    thick\n"
        "]\n"
        "(axis cs:%.4f,0) --\n"
        "(axis cs:%.4f,1)\n"
        "plot[\n"
        "    domain=%.4f:%.4f,\n"
        "    samples=30\n"
        "] (axis cs:\\x,1)\n"
        "-- (axis cs:%.4f,0)\n"
        "-- cycle;\n"
        "\n",

        color,
        start_angle,
        start_angle,
        start_angle,
        end_angle,
        end_angle
    );
}


/*
 * Writes a dynamic pie chart based on lexical categories.
 */
static void write_pie_chart(
    FILE *file,
    const BeamerStats *stats
) {

    fprintf(file,
        "\\begin{frame}{Distribución de categorías léxicas}\n"
        "\n"
    );

    if (stats->total_tokens == 0) {

        fprintf(file,
            "\\centering\n"
            "\n"
            "No se encontraron tokens para representar.\n"
            "\n"
            "\\end{frame}\n"
            "\n"
        );

        return;
    }

    double angle = 0.0;

    double keyword_angle =
        360.0 *
        (double) stats->keyword_count /
        (double) stats->total_tokens;

    double identifier_angle =
        360.0 *
        (double) stats->identifier_count /
        (double) stats->total_tokens;

    double constant_angle =
        360.0 *
        (double) stats->constant_count /
        (double) stats->total_tokens;

    double string_angle =
        360.0 *
        (double) stats->string_literal_count /
        (double) stats->total_tokens;

    double operator_angle =
        360.0 *
        (double) stats->operator_count /
        (double) stats->total_tokens;

    double punctuator_angle =
        360.0 *
        (double) stats->punctuator_count /
        (double) stats->total_tokens;

    double error_angle =
        360.0 *
        (double) stats->error_count /
        (double) stats->total_tokens;

    fprintf(file,
        "\\centering\n"
        "\n"
        "\\begin{tikzpicture}\n"
        "\n"
        "\\begin{polaraxis}[\n"
        "    hide axis,\n"
        "    xmin=0,\n"
        "    xmax=360,\n"
        "    ymin=0,\n"
        "    ymax=1,\n"
        "    width=7cm,\n"
        "    height=7cm\n"
        "]\n"
        "\n"
    );

    write_pie_sector(
        file,
        angle,
        angle + keyword_angle,
        "blue!65"
    );
    angle += keyword_angle;

    write_pie_sector(
        file,
        angle,
        angle + identifier_angle,
        "green!60"
    );
    angle += identifier_angle;

    write_pie_sector(
        file,
        angle,
        angle + constant_angle,
        "orange!70"
    );
    angle += constant_angle;

    write_pie_sector(
        file,
        angle,
        angle + string_angle,
        "cyan!60"
    );
    angle += string_angle;

    write_pie_sector(
        file,
        angle,
        angle + operator_angle,
        "violet!60"
    );
    angle += operator_angle;

    write_pie_sector(
        file,
        angle,
        angle + punctuator_angle,
        "yellow!70"
    );
    angle += punctuator_angle;

    write_pie_sector(
        file,
        angle,
        angle + error_angle,
        "red!65"
    );

    fprintf(file,
        "\\end{polaraxis}\n"
        "\n"
        "\\end{tikzpicture}\n"
        "\n"
        "\\scriptsize\n"
        "\n"
        "\\begin{tabular}{lll}\n"
        "\\textcolor{blue!65}{\\rule{0.25cm}{0.25cm}} "
        "Palabras reservadas: %zu &\n"
        "\\textcolor{green!60}{\\rule{0.25cm}{0.25cm}} "
        "Identificadores: %zu &\n"
        "\\textcolor{orange!70}{\\rule{0.25cm}{0.25cm}} "
        "Constantes: %zu \\\\[0.15cm]\n"
        "\n"
        "\\textcolor{cyan!60}{\\rule{0.25cm}{0.25cm}} "
        "Strings: %zu &\n"
        "\\textcolor{violet!60}{\\rule{0.25cm}{0.25cm}} "
        "Operadores: %zu &\n"
        "\\textcolor{yellow!70}{\\rule{0.25cm}{0.25cm}} "
        "Puntuación: %zu \\\\[0.15cm]\n"
        "\n"
        "\\textcolor{red!65}{\\rule{0.25cm}{0.25cm}} "
        "Errores: %zu & &\n"
        "\\end{tabular}\n"
        "\n"
        "\\end{frame}\n"
        "\n",

        stats->keyword_count,
        stats->identifier_count,
        stats->constant_count,
        stats->string_literal_count,
        stats->operator_count,
        stats->punctuator_count,
        stats->error_count
    );
}


/*
 * Writes the final presentation slide.
 */
static void write_end_slide(FILE *file) {

    fprintf(file,
        "\\begin{frame}\n"
        "\n"
        "\\centering\n"
        "\n"
        "\\Huge\n"
        "Fin\n"
        "\n"
        "\\vspace{0.7cm}\n"
        "\n"
        "\\Large\n"
        "Proyecto 1 --- Analizador Léxico\n"
        "\n"
        "\\end{frame}\n"
        "\n"
    );
}


/*
 * Generates the complete Beamer .tex file.
 */
int beamer_generate(
    const char *output_filename,
    const char *source_filename,
    const char *preprocessed_filename,
    const Token *tokens,
    size_t token_count
) {

    if (output_filename == NULL ||
        source_filename == NULL ||
        preprocessed_filename == NULL) {

        return 0;
    }

    if (tokens == NULL && token_count > 0) {
        return 0;
    }

    FILE *file = fopen(output_filename, "w");

    if (file == NULL) {

        fprintf(
            stderr,
            "Error: no se pudo crear %s\n",
            output_filename
        );

        return 0;
    }

    BeamerStats stats;

    calculate_stats(
        tokens,
        token_count,
        &stats
    );

    write_preamble(file);

    fprintf(file, "\\begin{document}\n\n");

    write_title_slide(file);

    write_process_slide(file);

    write_flex_slide(file);

    write_input_slide(
        file,
        source_filename,
        preprocessed_filename
    );

    write_statistics_slide(
        file,
        &stats
    );

    write_histogram(
        file,
        &stats
    );

    write_pie_chart(
        file,
        &stats
    );

    write_error_slide(
        file,
        tokens,
        token_count
    );

    /*
     * Pending:
     *
     * Generate slides containing the preprocessed source
     * with every lexeme colored according to the category
     * returned by the scanner.
     */

    write_end_slide(file);

    fprintf(file, "\\end{document}\n");

    fclose(file);

    return 1;
}